class Solution {
public:
    vector<int> findOriginalArray(vector<int>& changed) {
        if (changed.size() % 2 != 0) return {};
        sort(changed.begin(), changed.end());
        unordered_map<int, int> count;
        for (int x : changed) count[x]++;
        vector<int> res;
        for (int x : changed) {
            if (count[x] == 0) continue;
            if (count[2 * x] == 0 || (x == 0 && count[0] < 2)) return {};
            res.push_back(x);
            count[x]--;
            count[2 * x]--;
        }
        return res;
    }
};

class Solution {
    public int[] findOriginalArray(int[] changed) {
        if (changed.length % 2 != 0) return new int[0];
        Arrays.sort(changed);
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : changed) count.put(x, count.getOrDefault(x, 0) + 1);
        int[] res = new int[changed.length / 2];
        int idx = 0;
        for (int x : changed) {
            if (count.get(x) == 0) continue;
            int doubleX = 2 * x;
            if (count.getOrDefault(doubleX, 0) == 0 || (x == 0 && count.get(0) < 2)) return new int[0];
            res[idx++] = x;
            count.put(x, count.get(x) - 1);
            count.put(doubleX, count.get(doubleX) - 1);
        }
        return res;
    }
}

var findOriginalArray = function(changed) {
  if (changed.length % 2 !== 0) return [];
  changed.sort((a, b) => a - b);
  const count = new Map();
  for (const x of changed) count.set(x, (count.get(x) || 0) + 1);
  const res = [];
  for (const x of changed) {
    if ((count.get(x) || 0) === 0) continue;
    if ((count.get(2 * x) || 0) === 0 || (x === 0 && count.get(0) < 2)) return [];
    res.push(x);
    count.set(x, count.get(x) - 1);
    count.set(2 * x, count.get(2 * x) - 1);
  }
  return res;
};
